  useEffect(()=>{function key(e){if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();searchRef.current?.focus();}}window.addEventListener('keydown',key);return()=>window.removeEventListener('keydown',key);},[]);
  const record=(selectedKind==='entity'?entities:relations).find(r=>r.id===selected);
